<?php
require __DIR__.'/../config/database.php';require __DIR__.'/../config/auth.php';require_role(['staff']);$uid=$_SESSION['user']['id'];$st=$pdo->prepare("SELECT s.*,u.verification_status FROM staff s JOIN users u ON u.id=s.user_id WHERE s.user_id=?");$st->execute([$uid]);$staff=$st->fetch();if(!$staff)die('Staff profile not found.');
if(isset($_POST['checkin'])){$pdo->prepare("INSERT INTO work_attendance(user_id,work_date,check_in,status) VALUES(?,CURDATE(),NOW(),'present') ON DUPLICATE KEY UPDATE check_in=COALESCE(check_in,NOW()),check_out=NULL")->execute([$uid]);header('Location: dashboard.php');exit;}if(isset($_POST['checkout'])){$pdo->prepare("UPDATE work_attendance SET check_out=NOW() WHERE user_id=? AND work_date=CURDATE()")->execute([$uid]);header('Location: dashboard.php');exit;}
$st=$pdo->prepare("SELECT * FROM work_attendance WHERE user_id=? AND work_date=CURDATE()");$st->execute([$uid]);$today=$st->fetch();$checked=$today&&!empty($today['check_in'])&&empty($today['check_out']);
if(isset($_GET['task'],$_GET['status'])&&$checked&&in_array($_GET['status'],['in_progress','completed'],true)){$pdo->prepare("UPDATE staff_tasks SET status=? WHERE id=? AND staff_id=?")->execute([$_GET['status'],(int)$_GET['task'],$staff['id']]);header('Location: dashboard.php');exit;}$st=$pdo->prepare("SELECT t.*,f.name farm_name FROM staff_tasks t LEFT JOIN farms f ON f.id=t.farm_id WHERE t.staff_id=? ORDER BY t.task_date DESC,t.id DESC");$st->execute([$staff['id']]);$tasks=$st->fetchAll();$page_title='Staff Portal';require __DIR__.'/../partials/header.php';?>
<div class="container py-4"><div class="hero-top mb-4"><h2>Staff Portal</h2><p class="mb-0">Attendance first. Work actions are enabled only while checked in.</p></div><div class="row g-3 mb-3"><div class="col-md-4"><div class="cardx p-3"><div class="kpi-label">Staff Type</div><div class="metric" style="font-size:20px"><?=htmlspecialchars(ucwords(str_replace('_',' ',$staff['staff_type'])))?></div></div></div><div class="col-md-4"><div class="cardx p-3"><div class="kpi-label">Verification</div><div class="metric" style="font-size:20px"><?=ucfirst($staff['verification_status'])?></div></div></div><div class="col-md-4"><div class="cardx p-3"><a class="btn btn-outline-success w-100 mb-2" href="<?=url_path('account/profile.php')?>">Profile / NID</a><a class="btn btn-outline-dark w-100" href="<?=url_path('account/change_password.php')?>">Change Password</a></div></div></div><div class="cardx p-3 mb-3"><div class="d-flex justify-content-between align-items-center"><div><b>Today's Attendance</b><div class="small-muted"><?php if($today):?>In: <?=$today['check_in']?:'-'?> · Out: <?=$today['check_out']?:'-'?><?php else:?>Not checked in<?php endif;?></div></div><div class="d-flex gap-2"><form method="post"><button class="btn btn-success" name="checkin" <?=$checked?'disabled':''?>>Check In</button></form><form method="post"><button class="btn btn-outline-danger" name="checkout" <?=!$checked?'disabled':''?>>Check Out</button></form></div></div></div><?php if(!$checked):?><div class="alert alert-warning">Check in to start tasks or submit operational work.</div><?php endif;?><div class="smart-shortcuts mb-3"><a class="smart-tile" href="<?=url_path('staff/report_incident.php')?>"><b>📷 Problem Finder</b><span>Report farm/product issues</span></a><a class="smart-tile" href="<?=url_path('staff/deliveries.php')?>"><b>🚚 Deliveries</b><span>Accept & track delivery</span></a><a class="smart-tile" href="<?=url_path('staff/shop.php')?>"><b>🛒 Staff Shop</b><span>10% member discount</span></a><a class="smart-tile" href="<?=url_path('notifications.php')?>"><b>🔔 Notifications</b><span>Updates & accepted status</span></a></div><div class="mb-3"><?php if(in_array($staff['staff_type'],['delivery_man','multipurpose'],true)):?><a class="btn btn-primary" href="<?=url_path('staff/deliveries.php')?>">🚚 My Deliveries</a> <?php endif;?><a class="btn btn-success" href="<?=url_path('staff/collection.php')?>">➕ Production / Harvest Collection</a> <a class="btn btn-outline-success" href="<?=url_path('admin/operations/feed.php')?>">Feed Log</a> <a class="btn btn-outline-success" href="<?=url_path('admin/operations/medicine.php')?>">Medicine Usage</a></div><div class="cardx p-3"><h5>My Tasks</h5><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Farm</th><th>Task</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($tasks as $t):?><tr><td><?=$t['task_date']?></td><td><?=htmlspecialchars($t['farm_name']??'-')?></td><td><?=htmlspecialchars($t['title'])?></td><td><?=$t['status']?></td><td><?php if($checked&&$t['status']==='pending'):?><a class="btn btn-sm btn-primary" href="?task=<?=$t['id']?>&status=in_progress">Start</a><?php endif;?> <?php if($checked&&$t['status']!=='completed'):?><a class="btn btn-sm btn-success" href="?task=<?=$t['id']?>&status=completed">Complete</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>